import functools
import inspect
from typing import ForwardRef, Any, Callable, Dict
from fastapi.dependencies.utils import get_typed_signature, get_typed_annotation

def evaluate_forwardref(annotation, globalns, localns):
    if isinstance(annotation, ForwardRef):
        return eval(annotation.__forward_code__, globalns, localns)
    return annotation

# Mocking evaluate_forwardref because it's imported from pydantic in the real code
# but for this test we can just use a simple one or mock it.
# Actually, let's try to use the real get_typed_signature and see if it fails.

class MyModel:
    pass

def original_func(a: "MyModel"):
    return a

@functools.wraps(original_func)
def wrapped_func(a: "MyModel"):
    return original_func(a)

def test_wrapped_function_forward_ref():
    try:
        sig = get_typed_signature(wrapped_func)
        print("Success!")
    except NameError as e:
        print(f"Caught expected NameError: {e}")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_wrapped_function_forward_ref()

